  const latest = useRef(null); latest.current = doc;
  const load = useCallback(async () => { for (let n = 0; n < 4; n += 1) { try { const j = await work(cat.id, { op: 'ws_open', text: id, ...(latest.current?.id === id ? { ver: String(latest.current.versions || 0) } : {}) }); setErr(''); setDoc(old => ({ ...(old?.id === id ? old : {}), ...j.doc })); return; } catch (e) { if (!e.down || n === 3) { setErr(e.message); return; } await new Promise(r => setTimeout(r, 1200 * (n + 1))); } } }, [cat.id, id, work]);   // a service restarting never leaves a saved page looking blank
